    // Split the string into individual groups
    groups := strings.Split(paren_string, " ")
    // Initialize the output array
    output := make([]int, len(groups))

    // Iterate over each group
    for i, group := range groups {
        // Initialize the current level of nesting
        current_level := 0
        // Iterate over each character in the group
        for _, char := range group {
            // If the character is an opening parenthesis, increase the level of nesting
            if char == '(' {
                current_level += 1
            }
            // If the character is a closing parenthesis, decrease the level of nesting
            if char == ')' {
                current_level -= 1
            }
        }
        // Set the output value for the current group
        output[i] = current_level
    }
    return output
}

